+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL = Pattern.compile("[^@\\s]+@[^@\\s]+\\.[^@\\s]+");
+
+    private final MessageStore messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog unsavedDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(MessageStore messages) {
+        this.messages = messages;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setColspan(message, 2);
+        message.setWidthFull();
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(e -> sendMessage());
+        Shortcuts.addShortcutListener(this, this::sendIfEnabled, Key.ENTER);
+
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setItems(messages.findAll());
+
+        configureUnsavedDialog();
+
+        add(form, send, grid);
+    }
+
+    private void configureUnsavedDialog() {
+        unsavedDialog.setHeaderTitle("Discard your message?");
+        unsavedDialog.add(new Span("The form has unsent input. Discard it and leave this page?"));
+        unsavedDialog.setCloseOnEsc(false);
+        unsavedDialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            unsavedDialog.close();
+            pendingNavigation.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            unsavedDialog.close();
+            pendingNavigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        unsavedDialog.getFooter().add(keepEditing, discard);
+
+        add(unsavedDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsentInput()) {
+            pendingNavigation = event.postpone();
+            unsavedDialog.open();
+        }
+    }
+
+    private boolean hasUnsentInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void sendIfEnabled() {
+        if (send.isEnabled()) {
+            sendMessage();
+        }
+    }
+
+    private void sendMessage() {
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        clearValidation(name, email, phone, message);
+
+        boolean valid = true;
+        if (nameValue.isEmpty()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty()) {
+            if (!EMAIL.matcher(emailValue).matches()) {
+                markInvalid(email, "Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (phoneValue.isEmpty()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.isEmpty()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        messages.add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue));
+        grid.setItems(messages.findAll());
+        Notification.show("Message sent");
+
+        // Clearing fires value change events, which would re-enable Send, so disable it last.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private static void clearValidation(HasValidation... fields) {
+        for (HasValidation field : fields) {
+            field.setInvalid(false);
+        }
+    }
+
+    private static void markInvalid(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+}
